students = {}def create_student():    while True:        student_id = input("Enter student ID: ")        if student_id in students:            print("Student ID already exists! Please enter a unique ID.\n")        else:            break                surname = input("Enter surname: ").title()    firstname = input("Enter first name: ").title()        middle_initial = input("Enter middle initial: ")    if len(middle_initial) > 0:        middle_initial = middle_initial[0].upper()    else:        middle_initial = ""    birth_month = input("Enter birth month (e.g. 05): ")    birth_day = input("Enter birth day (e.g. 21): ")    birth_year = input("Enter birth year (e.g. 2004): ")    birthdate = (birth_month, birth_day, birth_year)    skills_input = input("Enter skills (comma-separated, e.g. Python, Git, SQL): ")    skills = [skill.strip() for skill in skills_input.split(",") if skill.strip()]    students[student_id] = {        "surname": surname,        "firstname": firstname,        "middle_initial": middle_initial,        "birthdate": birthdate,        "skills": skills    }    print("Student created!\n")def display_students():    if not students:        print("No students found.\n")        return    print("\nStudents:")    student_list = list(students.items())    for index, (student_id, data) in enumerate(student_list):        month, day, year = data["birthdate"]          skills_text = ", ".join(data["skills"]) if data["skills"] else "None"        print(f"[{index+1}] ID: {student_id} | {data['surname']}, {data['firstname']} {data['middle_initial']}. "              f"| Birthdate: {month}/{day}/{year} | Skills: {skills_text}")    print()def update_student():    if not students:        print("No students found.\n")        return    print("\nStudents:")    student_list = list(students.items())    for index, (student_id, data) in enumerate(student_list):        month, day, year = data["birthdate"]        skills_text = ", ".join(data["skills"]) if data["skills"] else "None"        print(f"[{index+1}] ID: {student_id} | {data['surname']}, {data['firstname']} {data['middle_initial']}. "              f"| Birthdate: {month}/{day}/{year} | Skills: {skills_text}")    try:        target_index = int(input("\nEnter the index number of the student to update: ")) - 1                if 0 <= target_index < len(student_list):            student_id = student_list[target_index][0]                        new_surname = input("Enter new surname: ").title()            new_firstname = input("Enter new first name: ").title()                        new_mi = input("Enter new middle initial: ")            if len(new_mi) > 0:                new_mi = new_mi[0].upper()            else:                new_mi = ""            new_month = input("Enter new birth month: ")            new_day = input("Enter new birth day: ")            new_year = input("Enter new birth year: ")            new_birthdate = (new_month, new_day, new_year)            new_skills_input = input("Enter new skills (comma-separated): ")            new_skills = [skill.strip() for skill in new_skills_input.split(",") if skill.strip()]            students[student_id] = {                "surname": new_surname,                "firstname": new_firstname,                "middle_initial": new_mi,                "birthdate": new_birthdate,                "skills": new_skills            }            print("Student updated!\n")        else:            print("Student not found.\n")    except ValueError:        print("Invalid input. Please enter a valid index number.\n")def delete_student():    if not students:        print("No students found.\n")        return    print("\nStudents:")    student_list = list(students.items())    for index, (student_id, data) in enumerate(student_list):        month, day, year = data["birthdate"]        skills_text = ", ".join(data["skills"]) if data["skills"] else "None"        print(f"[{index+1}] ID: {student_id} | {data['surname']}, {data['firstname']} {data['middle_initial']}. "              f"| Birthdate: {month}/{day}/{year} | Skills: {skills_text}")        try:        target_index = int(input("\nEnter the index number of the student to delete: ")) - 1                if 0 <= target_index < len(student_list):            student_id = student_list[target_index][0]            del students[student_id]            print("Student deleted!\n")        else:            print("Student not found.\n")    except ValueError:        print("Invalid input. Please enter a valid index number.\n")while True:    print("_______Student Management System_______")    print("1. Create student")    print("2. Display students")    print("3. Update student")    print("4. Delete student")    print("5. Exit")    choice = input("Choose an option: ")    if choice == "1":        create_student()    elif choice == "2":        display_students()    elif choice == "3":        update_student()    elif choice == "4":        delete_student()    elif choice == "5":        print("System shutting down.")        break    else:        print("Invalid choice.\n")